    n = int(input())
    a = list(map(int, input().split()))
    for i in range(n):
        a[i] = 1
    print(max_product(n, a))

if __name__ == "__main__":
    main()

def minOperations(n, k):
    operations = []
    for i in range(n):
        if i % k == 0:
            operations.append(i)
    return min(operations)

def max_subarray_sum(n, a):
    max_sum = 0
    for i in range(n):
        for j in range(i+1, n):
            if a[i] == a[j]:
                if a[i] > a[j]:
                    max_sum = max(max_sum, a[i] + a[j])
            else:
                if a[i] < a[j]:
                    max_sum = max(max_sum, a[i] + a[j])
    return max_sum

def main():
