def is_fascinating(n):
    # Check if the number is a multiple of 3
    if n % 3 != 0:
        return False

    # Check if the number is a multiple of 9
    if n % 9 != 0:
        return False

    # Check if the number is a multiple of 2
    if n % 2 != 0:
        return False

    # Check if the number is a multiple of 3 and 9
    if n % 3 == 0 and n % 9 == 0:
        return True

    return False
