def min_length(s):
    # Initialize the length of the minimized string
    min_length = len(s)

    # Initialize the index of the character to be deleted
    i = 0

    # Iterate over the string
    while i < len(s):
        # Choose the character at the current index
        c = s[i]

        # Delete the closest occurrence of c to the left of i (if any)
        if i > 0:
            if s[i - 1] == c:
                i -= 1
            else:
                i -= 1

        # Delete the closest occurrence of c to the right of i (if any)
        if i < len(s) - 1:
            if s[i + 1] == c:
                i += 1
            else:
                i += 1

        # Update the length of the minimized string
        min_length = min(min_length, i + 1)

    return min_length

