def partition(s, k):
    # Initialize dp
    dp = [[0] * (len(s) + 1) for _ in range(k + 1)]
    dp[0][0] = 1
    for i in range(1, k + 1):
        for j in range(1, len(s) + 1):
            dp[i][j] = min(dp[i - 1][j], dp[i][j - 1])
    return dp[k][len(s)]

