def count_ways(n, x):
    # Initialize the count
    count = 0

    # Iterate over all unique positive integers
    for i in range(1, n + 1):
        # Calculate the sum of the x^th power of the unique integers
        sum_of_powers = sum(i**x for i in range(1, n + 1))

        # Check if the sum is equal to n
        if sum_of_powers == n:
            count += 1

    # Return the count modulo 10^9 + 7
    return count % (10**9 + 7)

