def equalize(nums):
    n = len(nums)
    for i in range(n):
        for j in range(n):
            if i != j:
                nums[i], nums[(i - 1 + n) % n], nums[(i + 1) % n] = nums[i], nums[(i - 1 + n) % n], nums[(i + 1) % n]
    return min(n, len(nums))

