def find_pairs_with_distance(coordinates, k):
    # Initialize a dictionary to store the pairs
    pairs = {}

    # Iterate through each point in the coordinates
    for i in range(len(coordinates)):
        for j in range(i+1, len(coordinates)):
            # Calculate the distance between the two points
            distance = coordinates[i][0] ^ coordinates[j][0] + coordinates[i][1] ^ coordinates[j][1]

            # Check if the distance is equal to k
            if distance == k:
                # Add the pair to the dictionary
                pairs[(i, j)] = 1

    # Return the number of pairs
    return len(pairs)

def purchase_balance(purchase_amount):
    # Calculate the nearest multiple of 10 to the purchase amount
    nearest_multiple = 10
    for i in range(1, int(purchase_amount / nearest_multiple) + 1):
        if purchase_amount % i == 0:
            nearest_multiple = i
            break

    # Calculate the account balance
    account_balance = purchase_amount - nearest_multiple * purchase_amount
    return account_balance

