def max_gold(n, offers):
    max_gold = 0
    for i in range(n):
        for j in range(len(offers)):
            if i == 0 or i == n - 1 or j == 0 or j == len(offers) - 1:
                continue
            if offers[j][0] <= i <= offers[j][1] and offers[j][2] <= i <= offers[j][2] + offers[j][3]:
                max_gold = max(max_gold, offers[j][2] * offers[j][3])
    return max_gold

