    # Initialize the values
    for i in range(1, N + 1):
        A_values[i] = A_values[i - 1] + A_values[i]
    for i in range(1, M + 1):
        B_values[i] = B_values[i - 1] + B_values[i]

    # Initialize the sum of values
    for i in range(1, N + 1):
        sum_values[i] = sum_values[i - 1] + A_values[i]
    for i in range(1, M + 1):
        sum_values[i] = sum_values[i - 1] + B_values[i]

