    for i in range(N):
        Sellers[i] = A_i

    # Initialize Buyers
    for i in range(M):
        Buyers[i] = B_i

    # Initialize the number of people who may sell an apple for X yen
    for i in range(N):
        if Sellers[i] >= X:
