def max_weight_edges(N, D):
    edges = []
    for i in range(N):
        for j in range(i+1, N):
            edges.append((i, j, D[i, j]))

    edges.sort(key=lambda x: x[2])

    max_weight = 0
    for i in range(N):
        for j in range(i+1, N):
            if edges[i][0] == edges[j][0] and edges[i][1] == edges[j][1]:
                weight = edges[i][2] + edges[j][2]
                if weight > max_weight:
                    max_weight = weight

    return max_weight

