def find_min_value(D):
    x = 0
    y = 0
    min_value = float('inf')

    while x < D and y < D:
        if x**2 + y**2 - D < 0:
            min_value = min(min_value, x**2 + y**2 - D)
            x += 1
        else:
            y += 1

    return min_value
