def generate_output(N, Q, A, B, C, D):
    P = [[0 for _ in range(N)] for _ in range(N)]
    for i in range(N):
        for j in range(N):
            P[i][j] = (i + 1) % N
            P[j][i] = (j + 1) % N

    black_squares = 0
    for i in range(Q):
        for j in range(Q):
            A_i, B_i = A + i * N, B + j * N
            C_j, D_j = C + j * N, D + i * N
            if A_i < C_j and B_i < D_j:
                black_squares += 1

    return black_squares

