    pairs = [[0 for _ in range(N)] for _ in range(N)]

    # Initialize the weirdness of each pair
    for i in range(N):
        for j in range(N):
            if i != j:
                pairs[i][j] = abs(i-j)

    # Initialize the total weirdness
    total_weirdness = 0

