def intersect_chords(points):
    # Check if all points are distinct
    if not all(point == point[0] for point in points):
        return False

    # Initialize a dictionary to store the intersections
    intersections = {}

    # Iterate over all points
    for i in range(len(points) - 1):
        # Check if the points are on the same chord
        if points[i] == points[i + 1]:
            # If they are, add the intersection to the dictionary
            intersections[points[i]] = intersections.get(points[i], 0) + 1

    # Return the intersection count
    return intersections.get(points[0], 0) > 0

