def calculate_total_pay(N):
    total_pay = 0
    for i in range(N):
        x = i
        while True:
            if x < 2:
                break
            yen = x * 2
            x = x // 2
            x = x % 2
            if x == 1:
                x = 2
            else:
                x = 1
            total_pay += yen
    return total_pay

