def min_spanning_tree(edges):
    # Initialize the minimum spanning tree
    min_spanning_tree = [0] * (N + 1)

    # Initialize the minimum spanning tree
    for i in range(N):
        min_spanning_tree[i] = float('inf')

    # Initialize the minimum spanning tree
    for i in range(N):
        for j in range(i + 1, N):
            if edges[i][j] == 1:
                min_spanning_tree[j] = min(min_spanning_tree[j], min_spanning_tree[i] + edges[i][j])

    return min_spanning_tree[N]

