def check_consecutive_appearances(A, B):
    # Check if A and B are distinct
    if len(set(A)) != len(A):
        return False

    # Check if A and B are pairwise distinct
    if len(set(A) ^ set(B)) != len(A):
        return False

    # Check if A and B are sorted in ascending order
    if sorted(A) != sorted(B):
        return False

    # Check if C contains two consecutive elements appearing in A
    C = sorted(A + B)
    return len(set(C)) == 2

def bingo(N, T):
    # Initialize the grid
    grid = [[0 for _ in range(N)] for _ in range(N)]

    # Initialize the count of Bingo
    count = 0

    # Initialize the turn number
    turn = 0

    # Initialize the count of Bingo for each row
    for i in range(N):
        for j in range(N):
            if grid[i][j] == 0:
                grid[i][j] = 1
                count += 1

    # Initialize the count of Bingo for each column
    for i in range(N):
        for j in range(N):
            if grid[i][j] == 0:
                grid[i][j] = 1
                count += 1

    # Initialize the count of Bingo for each diagonal line
    for i in range(N):
        for j in range(N):
            if grid[i][j] == 0:
                grid[i][j] = 1
                count += 1

    # Check if Bingo is achieved within T turns
    while count < T:
        if count == 0:
            return turn
        turn += 1

    return -1

