def kSpecial(word, k):
    # Initialize the frequency of each character in the word
    freq = {}
    for i in range(len(word)):
        freq[word[i]] = word.count(word[i])

    # Initialize the count of each character in the word
    count = {}
    for i in range(len(word)):
        count[word[i]] = word.count(word[i])

    # Initialize the minimum number of characters to delete
    min_chars = 0

    # Iterate over the characters in the word
    for i in range(len(word)):
        # Check if the character is k-special
        if (freq[word[i]] - count[word[i]]) <= k:
            # If it is, delete the character
            word = word[:i] + word[i+1:]
            min_chars += 1

    return min_chars

