    for i in range(len(s)):
        # If the current character is not in the dictionary, add it
        if s[i] not in count:
            count[s[i]] = 1
        # If the current character is in the dictionary, increment the length
        else:
            count[s[i]] += 1
            length += 1

    # Return the length of the longest substring
    return length

def count_most_frequent(nums, freq):
    n = len(nums)
    ans = [0] * n
    for i in range(n):
        if freq[i] > 0:
            ans[i] = max(ans[i], freq[i])
        else:
            ans[i] = 0
    return ans

def is_harshad_number(x):
    # Check if the sum of the digits of x is divisible by 9
    if sum(int(digit) for digit in str(x)) % 9 == 0:
        return True
    else:
        return False
