        if nums[i] == nums[i+1]:
            count += 1
    return count

def maxDistance(nums):
    prime_nums = [num for num in nums if is_prime(num)]
    max_distance = max(abs(num - prime_num) for num in prime_nums)
    return max_distance

def is_prime(num):
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def encrypt(nums):
    encrypted_nums = []
    for num in nums:
        encrypted_nums.append(max(num, key=num))
    return sum(encrypted_nums)

def mark_array(nums, queries):
    n = len(nums)
    m = len(queries)

    # Initialize the answer array
    answer = [0] * m

    # Mark all elements in the array
    for i in range(n):
        for j in range(m):
            if nums[i] == queries[j][0]:
                nums[i] = queries[j][1]
                answer[j] += nums[i]
                break

    return answer

def min_cost(s):
    cost = {}
    for i in range(len(s)):
        if s[i] == '?':
            cost[i] = 0
        else:
            cost[i] = s[i] == '?' and cost.get(i-1, 0) + 1 or cost.get(i-1, 0)
    return min(cost.values())

def powerOfSubsequence(nums, k):
    if k == 0:
        return 0

    power = 0
    for i in range(len(nums)):
        if nums[i] == 0:
            continue
        power += 1
        for j in range(i, len(nums)):
            if nums[j] == 0:
                continue
            power += 1
    return power

def find_shortest_special_subarray(nums, k):
    # Initialize the result to -1
    result = -1

    # Iterate through the array
    for i in range(len(nums)):
        # Check if the current element is special
        if nums[i] & (nums[i] - 1) == 0:
            # If it is, add the length of the subarray to the result
            result = max(result, len(nums[i:]))

    return result

def score(s):
    score = 0
    for i in range(len(s) - 1):
        score += abs(ord(s[i]) - ord(s[i+1]))
    return score

def countSubarrays(nums):
