def add_to_nums(nums1, nums2):
    nums1.sort()
    nums2.sort()

    x = 0

    for i in range(len(nums1)):
        if nums1[i] > nums2[i]:
            nums1[i] += x
        else:
            nums2[i] += x

    return x

def find_min_nums(n, x):
    nums = [x]
    for i in range(n - 1):
        nums.append(nums[-1] & nums[i + 1])
    return min(nums)

def median(nums):
    unique_array = sorted(set(nums))
    if len(unique_array) % 2 == 0:
        return unique_array[len(unique_array) // 2]
    else:
        return unique_array[len(unique_array) // 2 - 1]

def minLengthAnagram(s):
    # Convert s to lowercase
    s = s.lower()

    # Create a dictionary to store the anagrams
    anagrams = {}

    # Iterate over each character in s
    for char in s:
        # Check if the character is already in the dictionary
        if char in anagrams:
            # If it is, return the length of the anagram
            return len(anagrams[char])
        # If it is not, add it to the dictionary
        anagrams[char] = 1

    # If no anagrams are found, return the length of s
    return len(s)

def minCostEqual(nums, cost1, cost2):
    # Initialize the result
    result = 0

    # Iterate through the array
    for i in range(len(nums)):
        # Choose an index i from nums and increase nums[i] by 1 for a cost of cost1
        if i < len(nums) - 1:
            nums[i] += 1
        else:
            nums[i] += 1

        # Choose two different indices i, j from nums and increase nums[i] and nums[j] by 1 for a cost of cost2
        if i < len(nums) - 2:
            nums[i] += 1
            nums[j] += 1
        else:
            nums[i] += 1
            nums[j] += 1

        # Calculate the total cost
        cost = cost1 + cost2
        result += cost

    # Return the minimum cost required to make all elements in the array equal
    return result % (10**9 + 7)

