def generate_stable_binary_arrays(zero, one, limit):
    # Initialize an empty list to store all possible stable binary arrays
    stable_binary_arrays = []

    # Generate all possible binary arrays of size zero to limit
    for i in range(zero, limit + 1):
        for j in range(zero, limit + 1):
            if i == 0 and j == 0:
                stable_binary_arrays.append([i, j])
            elif i == 0:
                stable_binary_arrays.append([i, j])
            elif j == 0:
                stable_binary_arrays.append([i, j])
            else:
                stable_binary_arrays.append([i, j])

    # Count the number of stable binary arrays
    total_stable_binary_arrays = len(stable_binary_arrays)

    # Return the total number of stable binary arrays
    return total_stable_binary_arrays % (10**9 + 7)

def permutation_difference(s, t):
    # Check if s and t are valid strings
    if not s or not t:
        return 0

    # Calculate the permutation difference
    diff = 0
    for i in range(len(s)):
        if s[i] != t[i]:
            diff += abs(i - t[i])
    return diff
print(permutation_difference("abc", "bac"))  # Output: 2
print(permutation_difference("abcde", "edbac"))  # Output: 12

def isSpecialArray(nums):
    # Check if the array is empty
    if not nums:
        return True

    # Check if the array is odd
    odd_count = 0
    for num in nums:
        if num % 2 != 0:
            odd_count += 1

    # Check if the array is even
    even_count = 0
    for num in nums:
        if num % 2 == 0:
            even_count += 1

    # Check if the array contains odd and even numbers
    if odd_count > 0 and even_count > 0:
        return True

    return False

def digit_diff(nums):
    total_diff = 0
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            diff = nums[i] - nums[j]
            total_diff += diff
    return total_diff

def countGoodPairs(nums1, nums2, k):
    n = len(nums1)
    m = len(nums2)
    good_pairs = 0

    for i in range(n):
        for j in range(m):
            if nums1[i] % nums2[j] * k == 0:
                good_pairs += 1

    return good_pairs

def partition(s):
    # Check if the string is balanced
    if not s:
        return []

    # Split the string into substrings
    substrings = []
    for i in range(len(s) - 1):
        substrings.append(s[i:i+2])

    # Check if the substrings are balanced
    for i in range(len(substrings)):
        if not all(substrings[i][j] == substrings[i][i+1] for j in range(1, len(substrings[i]))):
            return []

    # Return the minimum number of substrings
    return min(len(substrings), len(s) - len(substrings))

def bitwiseXOR(nums):
    result = 0
    for num in nums:
        if num == nums[0]:
            result ^= 1
        else:
            result ^= num
    return result

